def lpHaarWeightedSplitVector (S : LpHaarFiniteSplit)
    (c : Fin (2 ^ S.level) → 𝕜) : IntervalLp 𝕜 p :=
  ∑ j ∈ S.atoms, signedValue (S.signs j) (c j • lpHaarDyadic 𝕜 p S.level j)

